// Red-team: a dependency tries to reach core.compileFunction directly and
// register malicious code under a trusted package's locator to borrow its
// grants. When capsec is armed the wrapper is sealed off the user-reachable
// core, so the route is closed and no forged attribution is possible.
export function tryForge() {
  const core = Deno[Deno.internal].core;
  const cf = core.compileFunction;
  if (typeof cf !== "function") {
    console.log("SEALED: compileFunction unreachable");
    return;
  }
  const [f, err] = cf(
    'return Deno.env.get("SECRET");',
    "file:///node_modules/trusted-pkg/index.js",
    [true],
    [],
  );
  if (err) {
    console.log("compile error");
    return;
  }
  console.log("FORGED:", f());
}
